def collect():
    folder=t.OUT/'run-3'; runtime=json.loads((folder/'foundation-runtime.json').read_text())
    q.require(not runtime['errors'] and runtime['owned_runtime_destroyed'],'Runtime failure or cleanup incomplete')
    proof=json.loads((folder/'expectation-runtime.json').read_text())
    q.require(all(x['passed'] for x in proof['cases']),'Expectation failure')
    for name,h in runtime['recipe_hashes'].items(): q.require(q.sha((q.ROOT/'scripts/validation'/name).read_bytes())==h,'Recipe drift')
    activation=json.loads((folder/'test-policy-activation.json').read_text())
    audit=json.loads((folder/'test-admin-audit-chain.json').read_text())
    q.require(activation['proven'] and a.validate_audit(audit['records'],audit['trusted_tip'],activation['binding']),'Current target audit reconciliation failed')
    q.require(activation['binding']['decision_id']==a.DECISION and activation['binding']['deployment_id']!=json.loads((a.OUT/'run-5/test-policy-activation.json').read_text())['binding']['deployment_id'],'Historical target substituted')
    audit_expected=json.loads((t.OUT/'audit-binding-expectation.json').read_text())
    audit_expected.update(complete=True,current_target_chain_proven=True,missing=None,runtime_artifact=(folder/'test-admin-audit-chain.json').relative_to(q.ROOT).as_posix(),current_target_binding=activation['binding'],independently_retained_tip=audit['trusted_tip'],final_consumer_invalidation_proven=False)
    t.save('audit-binding-expectation.json',audit_expected)
    combined=json.loads((t.OUT/'expected-currentness-manifest-v3.json').read_text())
    combined['components']['audit_bindings_complete']=True
    combined['blockers']=['Full reachable effective ACL/function/operator/cast expectation closure missing','Readiness/guard proof identity and complete policy/readiness relationships incomplete','Rules for 21 fields specified, but full native/audit final-consumer invalidation remains pending']
    t.save('expected-currentness-manifest-v3.json',combined)
    failed=json.loads((t.OUT/'run-1/foundation-runtime.json').read_text())
    q.require(failed['owned_runtime_destroyed'] and len(failed['errors'])==1,'Failed attempt cleanup/accounting differs')
    t.save('development-attempts.json',dict(failed_attempt='run-1',errors=failed['errors'],destroyed=True,correction='Expand NULL column ACL directly; no zero-dimensional empty ACL passed to aclexplode',access_only_preparation='run-2',accepted_final='run-3',superseded_attempts_not_counted_as_new_tests=True))
    stopped=dict(status='NOT_EXECUTED_PHASE_8_EXPECTATION_GATE_FAIL',reason='Complete expected manifest is NO; user explicitly requires STOP after evidence',production_semantics_claimed=False)
    for name in ['mutation-detection-v2.json','mutator-authority-map.json','governed-transition-boundary.json','qualification-currentness-generation.json','t10-invalidation-protocol.json','t10-toctou-v2.json','unknown-outcome-currentness.json','currentness-replay.json','final-currentness-observer.json','prebinding-proof-v3.json','currentness-coherence.json']:
        t.save(name,stopped)
    t.save('expectation-gate.json',dict(complete_currentness_gate='FAIL',stop_phase=8,new_expectation_assertions=len(proof['cases']),direct_S04_acl_entries=proof['effective_entries'],direct_S04_access_submanifest_runtime_match=True,full_effective_ACL_manifest_complete=False,unresolved_rule_definitions=0,runtime_proof_pending=21,foundation_assertions_reused=93,activation_audit_native_prerequisite_assertions_reused=39,final_runtime_assertions=len(runtime['cases']),final_observer_measurement_samples=0,incidental_reused_native_observations=7,accepted_assertion_failures=0,development_attempt_failures=1,protected_generation_protocol_implemented=False))
    t.save('READINESS.json',dict(created=False,s04_executed=False,pipeline_implemented=False,canonical_v043_executed=False,production_contacted=False,shared_db_contacted=False,execution_authority='BLOCKED',recovery_authority='BLOCKED',room_operational=False))
    report=q.ROOT/'docs/evidence/PACKAGE-0090-t10-governed-currentness-closure.md'
    report.write_text('''# Package 0090 T10 governed currentness closure\n\nCOMPLETE_CURRENTNESS_GATE=FAIL. The explicit phase 8 expectation gate requires STOP after evidence while the complete independent manifest remains NO. No mutation/invalidation protocol, qualification generation, TOCTOU/replay/unknown campaign, final observer, READY, S04 or concurrent benchmark was executed.\n\nAll 21 previously generic unresolved fields now have individual expected source/rule, classification, mutator, invalidation and T10 requirements. This closes rule definitions only: all 21 independent runtime proofs remain pending. A count of zero undefined rules does not grant prebinding or currentness authority. Native generation/identity/enrollment/channel/functional witness rules retain the seven-participant frozen design and trusted external host-root boundary. No runtime value is hard-coded before allocation and no historical proof is reused for a current target.\n\nAn independently computed direct S04 access submanifest covers 3848 positive/negative/grant-option entries for PUBLIC, four restricted services and eight Package owners across database privileges, public/pg_catalog schema privileges, S04 EXECUTE, four direct public relations and their columns. GRANT/REVOKE and owners are replayed from frozen canonical AST; defaults and approved qualification bootstrap grants are explicitly identified. Membership-derived grants are absent by the independently expected empty role graph; runtime graph attributes/memberships are separately checked. PUBLIC is observed via ACL expansion, never a synthetic login. Runtime observations never define expected values.\n\nThis submanifest is not the complete effective first-path catalog: reachable builtins/operators/casts, wider currentness/readiness functions, sequence/default/bootstrap closure and all 33 unbound S04 resolution contexts remain unclosed. The S04 function body digest, owner, language, security mode, volatility, strictness, parallel mode and search_path are independently expected and compared without invoking S04. The exact restricted role graph is independently specified; observed OIDs are not deterministic expected constants or an authenticated registered auditor slot.\n\nAudit expectations retain the accepted TEST decision/approval/change/actor and one-capture activation recipe, exact status/hash/context chain and independently trusted terminal tip. No newly committed current-target activation/audit was performed. Historical audit evidence for a destroyed target is not substituted for a current binding. Policy/readiness expectations remain incomplete until full guard/currentness proof identities are frozen and independently validated. Empty target state cannot fill those gaps.\n\nThe scoped blockers are full reachable effective ACL/function expectation closure; current audit/policy/readiness proof bindings; and the still-pending independent runtime/invalidation proof for the specified native/audit rules. Existing TEST authority is not withdrawn. The later qualification-only monotonic generation and governed final-decision boundary are not implemented because the expectation stop boundary was reached. No production revision semantics or timing success is claimed.\n\nThe campaign used one fresh labelled disposable target with the unchanged V001–V042 baseline and separately derived qualification body. Canonical V043 and its fence remained unchanged and unexecuted. The owned target and private credentials were destroyed. NEXT, not executed: independently close the reachable effective function/operator/cast/default ACL and audit/policy/readiness expectations, then qualify a governed external decision fence and invalidation generation in the authorized TEST scope.\n''',encoding='utf-8')
    final_report=report.read_text(encoding='utf-8').replace('No newly committed current-target activation/audit was performed. Historical audit evidence for a destroyed target is not substituted for a current binding.','The accepted TEST activation/audit recipe committed the exact approved policy on the current target and reconciled its external PREPARED/COMMITTED chain against the independently retained terminal tip. Historical destroyed-target evidence was not substituted for this binding. Final-consumer audit invalidation remains unproven.')
    final_report=final_report.replace('current audit/policy/readiness proof bindings;','complete readiness/guard-proof and policy/readiness relationship bindings;')
    report.write_text(final_report+'\nValidation: '+str(len(proof['cases']))+' new expectation assertions passed with Python -O, plus 132 reused foundation/activation/audit/native prerequisite assertions ('+str(len(runtime['cases']))+' final runtime assertions). No final currentness-observer measurements; seven incidental native age observations belong to the reused prerequisite, not a benchmark. One superseded ACL-expansion development attempt failed and was corrected; all three owned targets were destroyed, with zero accepted runtime assertion failures. Policy activation created no READY/header/original/S04 state.\n',encoding='utf-8')
    import package_0090_t10_audit_expectations as wrapper
    inputs={p.relative_to(q.ROOT).as_posix():q.sha(p.read_bytes()) for p in [Path(__file__),Path(t.__file__),Path(wrapper.__file__),q.ROOT/'scripts/validation/package_0090_active_foundation.py']}
    outputs={p.relative_to(q.ROOT).as_posix():q.sha(p.read_bytes()) for p in sorted(t.OUT.rglob('*')) if p.is_file() and p.name!='SHA256-MANIFEST.json'}
