    t.save('SHA256-MANIFEST.json',dict(inputs=inputs,outputs=outputs,baseline=t.BASELINE,canonical_git_lf_sha256=q.SOURCE_HASH))
    print(json.dumps(dict(gate='FAIL',stop_phase=8,new_assertions=len(proof['cases']),acl_entries=proof['effective_entries'],runtime_match=True,unresolved_rule_definitions=0,runtime_proof_pending=21)))


